//! owner: 008-layout-engine — incremental box-tree construction (015 PERF-1, closes beta RX-1)
//!
//! Box generation is a pure function of the DOM, the mapped styles and a little builder state, so a box
//! subtree generated by an element E can be taken over from the previous tree when nothing it was built
//! from changed:
//!
//! * no DOM change inside E (the journal since the previous tree names no node of E's subtree: no
//!   child-list, text, attribute, control-state or picker change; `BoxDamage`),
//! * no mapped style of E or of a node below it changed (the `Arc`s of the source's style maps are
//!   compared with those the previous build used, then the values),
//! * E is entered with the same propagated text decorations (the only part of the parent's box style
//!   that box generation hands down to an element),
//! * E's build read no counter or quote (it may write counters: below) and no image state (images
//!   change with resource completions, which the journal does not record),
//! * E generated exactly one box subtree (a block-level, atomic or replaced box; a table wrapper):
//!   inline boxes split around blocks and `display: contents` are rebuilt.
//!
//! Counters: an element that wrote counters (`counter-reset`, `counter-increment`, list items) and did
//! not read any can still be taken over, but its writes are then not replayed. They are unobservable
//! unless something reads a counter; when the new build read one and took over a writer, the build is
//! redone in full (`build_box_tree_reusing`).
//!
//! A taken-over subtree is copied into the new arena in pre-order with its box ids shifted, so the new
//! tree is exactly the tree a full build makes (box ids are pre-order indexes). Its reports are
//! replayed in place, which keeps the de-duplicated report order of a full build. The full build stays
//! the oracle: `incremental_vs_cold.rs` and the randomized pipeline harness compare every step.

use std::collections::{HashMap, HashSet};
use std::sync::Arc;

use ui4me_engine_types::diag::FeatureId;
use ui4me_engine_types::ids::NodeId;
use ui4me_engine_types::stage::Stage;

use super::build::{BoxId, BoxKind, BoxOwner, BoxTag, BoxTree, Proto};
use super::{BoxStyle, PseudoKind, TableTag};

/// The style maps of a source (`StyledSource::style_maps`).
#[derive(Clone)]
pub struct StyleMaps {
    pub elements: Arc<HashMap<NodeId, Arc<BoxStyle>>>,
    pub pseudos: Arc<HashMap<(NodeId, PseudoKind), Arc<BoxStyle>>>,
}

/// The DOM nodes whose content, children, attributes or control state changed since the DOM revision
/// the previous box tree was built from (from the DOM journal). A text node stands for its parent.
#[derive(Clone, Debug, Default)]
pub struct BoxDamage {
    pub nodes: Vec<NodeId>,
}

/// One report call made while an element's boxes were generated (replayed on reuse).
pub(crate) type ReportCall = (FeatureId, Stage, NodeId);

/// What the previous build knows about an element whose box subtree can be taken over.
#[derive(Clone, Debug)]
pub(crate) struct RootMemo {
    /// The first (outermost) box of the element's subtree.
    pub root: BoxId,
    /// The propagated decorations the element was entered with.
    pub decorations: Arc<[crate::text::paragraph::DecorationLayer]>,
    /// The report calls of its build, in order.
    pub reports: Vec<ReportCall>,
    /// Its build wrote counters (module docs).
    pub writes: bool,
}

/// What a box tree keeps of its build for the next incremental build.
pub(crate) struct BuildMemo {
    pub styles: StyleMaps,
    pub roots: HashMap<NodeId, RootMemo>,
    /// One past the last box of each box's subtree (pre-order).
    pub subtree_end: Vec<u32>,
    /// The DOM revision of the build.
    pub dom_revision: u64,
}

impl std::fmt::Debug for BuildMemo {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("BuildMemo")
            .field("roots", &self.roots.len())
            .finish()
    }
}

/// The previous tree and what must be rebuilt.
pub(crate) struct ReuseCtx<'a> {
    pub old: &'a BoxTree,
    pub memo: &'a BuildMemo,
    /// Nodes that changed, and their ancestors: their subtrees are not taken over.
    pub unclean: HashSet<NodeId>,
}

/// An element's build, as the builder records it for the next build.
pub(crate) struct Candidate {
    pub node: NodeId,
    pub wrapper: bool,
    pub decorations: Arc<[crate::text::paragraph::DecorationLayer]>,
    pub reports: Vec<ReportCall>,
    pub writes: bool,
}

pub(crate) fn subtree_ends(tree: &BoxTree) -> Vec<u32> {
    let n = tree.boxes.len();
    let mut end = vec![0u32; n];
    for i in (0..n).rev() {
        let b = &tree.boxes[i];
        end[i] = match b.children.last() {
            Some(c) => end[c.0 as usize],
            None => i as u32 + 1,
        };
    }
    end
}

fn same_style(a: &Arc<BoxStyle>, b: &Arc<BoxStyle>) -> bool {
    Arc::ptr_eq(a, b) || **a == **b
}

/// The reuse context of a build over `src` against `old`, or `None` when the build must be full.
pub(crate) fn reuse_ctx<'a>(
    src: &impl super::StyledSource,
    old: &'a BoxTree,
    damage: &BoxDamage,
) -> Option<ReuseCtx<'a>> {
    let memo = old.memo.as_deref()?;
    let maps = src.style_maps()?;
    if old.document != src.document() {
        return None;
    }
    let mut changed: Vec<NodeId> = damage.nodes.clone();
    for (n, s) in maps.elements.iter() {
        match memo.styles.elements.get(n) {
            Some(o) if same_style(o, s) => {}
            _ => changed.push(*n),
        }
    }
    for n in memo.styles.elements.keys() {
        if !maps.elements.contains_key(n) {
            changed.push(*n);
        }
    }
    for ((n, k), s) in maps.pseudos.iter() {
        match memo.styles.pseudos.get(&(*n, *k)) {
            Some(o) if same_style(o, s) => {}
            _ => changed.push(*n),
        }
    }
    for (n, k) in memo.styles.pseudos.keys() {
        if !maps.pseudos.contains_key(&(*n, *k)) {
            changed.push(*n);
        }
    }
    let mut unclean = HashSet::with_capacity(changed.len() * 8);
    for n in changed {
        let mut cur = Some(n);
        while let Some(c) = cur {
            if !unclean.insert(c) {
                break;
            }
            cur = src.parent(c);
        }
    }
    Some(ReuseCtx { old, memo, unclean })
}

/// The box subtree of `id` in `old` as protos (for the few places that edit a child's subtree after it
/// was built: a list item's marker, a fieldset's rendered legend). Inserting the result gives the same
/// boxes.
pub(crate) fn expand(old: &BoxTree, id: BoxId) -> Proto {
    let b = old.get(id);
    let children = || {
        b.children
            .iter()
            .map(|c| expand(old, *c))
            .collect::<Vec<_>>()
    };
    let pseudo = |o: BoxOwner| match o {
        BoxOwner::Pseudo(_, k) => Some(k),
        _ => None,
    };
    match &b.kind {
        BoxKind::BlockContainer { .. } | BoxKind::InlineBlock { .. } => Proto::Block {
            owner: b.owner,
            style: (*b.style).clone(),
            children: children(),
            inner: b.inner,
            list_item: b.list_item,
            tag: b.tag,
            atomic: matches!(b.kind, BoxKind::InlineBlock { .. }),
        },
        BoxKind::InlineBox => Proto::Inline {
            node: b.owner.node(),
            pseudo: pseudo(b.owner),
            style: (*b.style).clone(),
            children: children(),
        },
        BoxKind::TextRun(t) => Proto::Text {
            text: t.clone(),
            style: (*b.style).clone(),
            owner: b.owner.node(),
            pseudo: pseudo(b.owner),
        },
        BoxKind::Replaced(r) => Proto::Replaced {
            node: b.owner.node(),
            pseudo: pseudo(b.owner),
            style: (*b.style).clone(),
            content: r.clone(),
        },
    }
}

/// The table tag of a taken-over subtree's root.
pub(crate) fn reused_tag(tag: BoxTag) -> Option<TableTag> {
    match tag {
        BoxTag::Table(t) => Some(t),
        _ => None,
    }
}
